const test = require('node:test');
const assert = require('node:assert');
const { clamp, isPrime } = require('./mathutils.js');

test('clamp keeps in-range value unchanged', () => assert.strictEqual(clamp(5, 0, 10), 5));
test('clamp raises below-min value to min', () => assert.strictEqual(clamp(-5, 0, 10), 0));
test('clamp lowers above-max value to max', () => assert.strictEqual(clamp(15, 0, 10), 10));

test('isPrime true for 7', () => assert.strictEqual(isPrime(7), true));
test('isPrime false for 8', () => assert.strictEqual(isPrime(8), false));
test('isPrime false for 1', () => assert.strictEqual(isPrime(1), false));
test('isPrime false for 0', () => assert.strictEqual(isPrime(0), false));
